 47	/// Validate that the local token matches the expected token (from DB).
 48	/// Returns Ok(()) if they match or if no local session file exists (backward compat).
 49	/// Errors with "Session replaced" if the local token differs from expected.
 50	pub fn validate(sessions_dir: &Path, agent_id: &str, expected_token: &str) -> Result<()> {
 51	    let current = read_token(sessions_dir, agent_id)?;
 52	    match current {
 53	        None => Ok(()), // No session file = agent joined before this feature, skip
 54	        Some(token) if token == expected_token => Ok(()),
 55	        Some(_) => bail!(
 56	            "Session replaced. Another terminal joined as {agent_id}. \
 57	             Re-join with a different ID (e.g. squad join {agent_id}-2 --role <your-role>)."
 58	        ),
 59	    }
